const capped = UP_TO_N.exec(text);
if (capped) {
  // Group 1 is mandatory in UP_TO_N, so a match always populates it.
  const candidate = capped[1]!;
  // Plain integer (e.g. "7")
  const limit = Number.parseInt(candidate, 10);
  if (!Number.isNaN(limit) && limit >= 1 && limit <= 100) return limit;
  // Otherwise look for spelled-out number (e.g. "seven")
  const limitWord = NUMBER_WORDS[candidate.toLowerCase()];
  if (limitWord) return limitWord;
  /**
   * The number is genuinely unparseable (not an integer, not a known word).
   * e.g. some unexpected token in oracle text. Emit a warning so this
   * doesn't go silently to 1.
   */
  console.warn(`singletonLimit: unable to parse limit "${candidate}" in "${text}". Returning conservative default of 1.`);
}

return 1;

